def wrap(text, width):
    import textwrap
    return textwrap.fill(text, width)

def slugify(name):
    parts = name.strip('-').split()
    if parts[0].startswith('-'):
        parts[0] = parts[0][1:]
    if parts[-1].endswith('-'):
        parts[-1] = parts[-1][:-1]
    return '-'.join(part.lower() for part in parts)
